    private static string Id()=>Guid.NewGuid().ToString("N");
    private static string Command()=>Guid.NewGuid().ToString("D");
    private static async Task<JsonNode> Body(HttpResponseMessage response,HttpStatusCode expected=HttpStatusCode.OK,string? capture=null)
    {
        using(response){var body=await response.Content.ReadAsStringAsync();Assert.True(response.StatusCode==expected,$"HTTP {(int)response.StatusCode}, expected {(int)expected}: {body}");var directory=Environment.GetEnvironmentVariable("SHOP_SOURCING_WIRE_DIR");if(capture is not null&&!string.IsNullOrEmpty(directory)){Directory.CreateDirectory(directory);foreach(var name in capture switch{"mutation"=>new[]{capture,"submit"},"customer-detail"=>new[]{capture,"detail"},"customer-page"=>new[]{capture,"page"},"customer-events"=>new[]{capture,"events"},"submit-receipt"=>new[]{capture,"receipt"},_=>new[]{capture}})await File.WriteAllTextAsync(Path.Combine(directory,name+".json"),body);}return JsonNode.Parse(body)!;}
    }
    private async Task<(HttpClient Client,string Owner)> Customer()
    {
        await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="sourcing"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,DisplayName="Synthetic sourcing SQL customer"};Assert.True((await users.CreateAsync(user,fixture.Sql.Password)).Succeeded);
        var session=await scope.ServiceProvider.GetRequiredService<AuthService>().PasswordAsync(new(name,fixture.Sql.Password),true,true,false,CancellationToken.None);Assert.False(session.RequiresMfa);var client=fixture.Sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");client.DefaultRequestHeaders.Authorization=new("Bearer",session.AccessToken);return(client,user.Id);
    }
    private async Task<string> Listing(string? price=null,string availability="unknown",string? number=null,string? boolean=null,ModelAttributeInput[]? extra=null)
    {
        var key=Id();var attributes=new List<ModelAttributeInput>{new("battery",TextFa:"باتری نمونه",TextEn:"Sample battery")};if(number is not null)attributes.Add(new(number,Number:0));if(boolean is not null)attributes.Add(new(boolean,Bool:false));if(extra is not null)attributes.AddRange(extra);
        var model=new CatalogModelInput("phones","samsung","sourcing-"+key,[new("fa","گوشی درخواست نمونه "+key,"متن مصنوعی SQL"),new("en","Synthetic sourcing phone "+key,"Synthetic SQL data")],attributes.ToArray(),["/products/phone-green.svg"],null);
        var now=DateTimeOffset.UtcNow;var details=new MarketDetailsInput("Published","qa-sourcing",key,"منبع نمونهٔ درخواست","Synthetic sourcing source",null,availability,price is null&&availability=="unknown"?null:now.AddHours(-1),price is null&&availability=="unknown"?null:now.AddDays(1),price,true);
        return(await Body(await fixture.Writer.PostAsJsonAsync("/api/admin/market/models",new CreateMarketModelInput(model,details))))["id"]!.GetValue<string>();
    }
    private static SourcingSubmitInput Input(JsonNode cart,string? command=null,string? note=null)=>new(command??Command(),cart["version"]!.GetValue<string>(),cart["lines"]!.AsArray().Select(l=>new SourcingExpectedInput(l!["listingId"]!.GetValue<string>(),l["candidate"]!["fingerprint"]!.GetValue<string>())).ToArray(),note);
    private static async Task<JsonNode> Select(HttpClient client,string listing,int quantity=1,string? capture=null)
    {
        var before=await Body(await client.GetAsync("/api/cart/en/sourcing"));return await Body(await client.PutAsJsonAsync("/api/cart/en/sourcing",new CartSourcingInput([new(listing,quantity)],before["version"]?.GetValue<string>())),capture:capture);
    }
    private static Task<JsonNode> Submit(HttpClient client,SourcingSubmitInput input,string? capture=null)=>ReadPost(client,"/api/cart/en/sourcing/submit",input,HttpStatusCode.Created,capture);
    private static async Task<JsonNode> ReadPost(HttpClient client,string route,object input,HttpStatusCode expected=HttpStatusCode.OK,string? capture=null)=>await Body(await client.PostAsJsonAsync(route,input),expected,capture);
    private async Task<(int Variants,int Stock,long OnHand,long Reserved,int Orders)> Counters()
    {
        await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();var services=scope.ServiceProvider;var stock=services.GetRequiredService<InventoryDbContext>().Stock;return(await services.GetRequiredService<CatalogDbContext>().Variants.CountAsync(),await stock.CountAsync(),await stock.SumAsync(s=>(long)s.OnHand),await stock.SumAsync(s=>(long)s.Reserved),await services.GetRequiredService<SalesDbContext>().Orders.CountAsync());
    }
    [Fact] public async Task SubmissionPersistsTypedHistoricalSnapshotAndProtectsNoteWithoutCreatingFinancialState()
    {
        var number="sourcing-num-"+Id();var boolean="sourcing-bool-"+Id();var select="sourcing-select-"+Id();var multi="sourcing-multi-"+Id();var black=Id();var usb=Id();var typec=Id();
        await using(var setup=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=setup.ServiceProvider.GetRequiredService<CatalogDbContext>();db.AttributeDefinitions.AddRange(new AttributeDefinition{Id=number,Key=number,DataType=AttributeDataType.Number,Unit="GB",Translations=[new(){Locale="fa",Name="ظرفیت",Unit="گیگابایت"},new(){Locale="en",Name="Capacity",Unit="Gigabytes"}]},new AttributeDefinition{Id=boolean,Key=boolean,DataType=AttributeDataType.Bool,Translations=[new(){Locale="fa",Name="پلمب"},new(){Locale="en",Name="Sealed"}]},new AttributeDefinition{Id=select,Key=select,DataType=AttributeDataType.Select,Translations=[new(){Locale="fa",Name="رنگ"},new(){Locale="en",Name="Colour"}],Options=[new(){Id=black,Value="black",LabelFa="مشکی",LabelEn="Black"}]},new AttributeDefinition{Id=multi,Key=multi,DataType=AttributeDataType.MultiSelect,Translations=[new(){Locale="fa",Name="درگاه‌ها"},new(){Locale="en",Name="Ports"}],Options=[new(){Id=usb,Value="usb",LabelFa="یو اس بی",LabelEn="USB"},new(){Id=typec,Value="typec",LabelFa="تایپ سی",LabelEn="Type C"}]});db.CategoryAttributes.AddRange(new CategoryAttribute{CategoryId="phones",AttributeId=number},new CategoryAttribute{CategoryId="phones",AttributeId=boolean},new CategoryAttribute{CategoryId="phones",AttributeId=select},new CategoryAttribute{CategoryId="phones",AttributeId=multi});await db.SaveChangesAsync();}
        var listing=await Listing("9007199254740993","available",number,boolean,[new(select,OptionId:black),new(multi,OptionIds:[usb,typec])]);var person=await Customer();using var customer=person.Client;var baseline=await Counters();var cart=await Select(customer,listing,3,capture:"cart");var input=Input(cart,note:"یادداشت خصوصی مصنوعی 09123456789");var saved=await Submit(customer,input,"mutation");var id=saved["id"]!.GetValue<string>();await ReadPost(customer,"/api/cart/en/sourcing/submit",input,capture:"replay");Assert.Equal("Submitted",saved["state"]!.GetValue<string>());Assert.True(saved["requestOnly"]!.GetValue<bool>());Assert.False(saved["canPay"]!.GetValue<bool>());
        var detail=await Body(await customer.GetAsync("/api/sourcing/requests/"+id),capture:"customer-detail");Assert.Equal(input.Note,detail["note"]!.GetValue<string>());var line=detail["lines"]![0]!;Assert.Equal("9007199254740993",line["referencePriceRial"]!.GetValue<string>());var attributes=line["model"]!["attributes"]!.AsArray();Assert.Equal(0m,decimal.Parse(attributes.Single(a=>a!["attributeId"]!.GetValue<string>()==number)!["number"]!.GetValue<string>(),System.Globalization.CultureInfo.InvariantCulture));Assert.False(attributes.Single(a=>a!["attributeId"]!.GetValue<string>()==boolean)!["bool"]!.GetValue<bool>());Assert.False(detail["summary"]!.AsObject().ContainsKey("ownerId"));Assert.False(detail["canPay"]!.GetValue<bool>());
        Assert.Equal(5,attributes.Count);var numeric=attributes.Single(a=>a!["attributeId"]!.GetValue<string>()==number)!;Assert.Equal("GB",numeric["unit"]!.GetValue<string>());Assert.False(string.IsNullOrWhiteSpace(numeric["unitFa"]!.GetValue<string>()));Assert.False(string.IsNullOrWhiteSpace(numeric["unitEn"]!.GetValue<string>()));Assert.Equal("مشکی",attributes.Single(a=>a!["attributeId"]!.GetValue<string>()==select)!["options"]![0]!["labelFa"]!.GetValue<string>());var ports=attributes.Single(a=>a!["attributeId"]!.GetValue<string>()==multi)!["options"]!.AsArray();Assert.Equal(2,ports.Count);Assert.Contains(ports,o=>o!["labelFa"]!.GetValue<string>()=="تایپ سی"&&o["labelEn"]!.GetValue<string>()=="Type C");
        Assert.Empty((await Body(await customer.GetAsync("/api/cart/en/sourcing")))["lines"]!.AsArray());Assert.Equal(baseline,await Counters());
        await using(var check=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=check.ServiceProvider.GetRequiredService<MarketDbContext>();var row=await db.SourcingRequests.SingleAsync(r=>r.Id==id);Assert.DoesNotContain(input.Note!,row.ProtectedNote);Assert.True(row.ContainsDemo);Assert.Single(await db.SourcingRequestEvents.Where(e=>e.RequestId==id).ToArrayAsync());var receipt=await db.SourcingCommandReceipts.SingleAsync(r=>r.TargetId==id);Assert.DoesNotContain(input.Note!,receipt.ResultJson);Assert.DoesNotContain("09123456789",receipt.ResultJson);}
        await using(var edit=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=edit.ServiceProvider.GetRequiredService<CatalogDbContext>();var option=await db.AttributeOptions.SingleAsync(o=>o.AttributeId==multi&&o.Id==typec);option.LabelFa="عنوان تازه";option.LabelEn="Changed";var definition=await db.AttributeDefinitions.SingleAsync(a=>a.Id==number);definition.Unit="MB";await db.SaveChangesAsync();var market=edit.ServiceProvider.GetRequiredService<MarketDbContext>();var source=await market.Listings.SingleAsync(l=>l.Id==listing);source.ReferencePriceRial=1;source.SourceNameEn="Changed source";await market.SaveChangesAsync();}
        Assert.Equal(detail["lines"]!.ToJsonString(),(await Body(await customer.GetAsync("/api/sourcing/requests/"+id)))["lines"]!.ToJsonString());
        await Body(await customer.GetAsync("/api/sourcing/requests"),capture:"customer-page");await Body(await customer.GetAsync("/api/sourcing/requests/"+id+"/events"),capture:"customer-events");using var sales=await fixture.ReuseStaff("SalesManager");await Body(await sales.GetAsync("/api/admin/sourcing/requests"),capture:"admin-page");await Body(await sales.GetAsync("/api/admin/sourcing/requests/"+id),capture:"admin-detail");await Body(await sales.GetAsync("/api/admin/sourcing/requests/"+id+"/events"),capture:"admin-events");
        // Keep the response-only wire fixture in one request lifecycle. Other facts
        // exercise replay/transition behavior with separately named captures.
        var submittedReceipt=await Body(await customer.GetAsync("/api/sourcing/requests/commands/submit/"+input.RequestId),capture:"submit-receipt");Assert.Equal(id,submittedReceipt["id"]!.GetValue<string>());Assert.True(submittedReceipt["replayed"]!.GetValue<bool>());Assert.Equal(saved["version"]!.GetValue<string>(),submittedReceipt["version"]!.GetValue<string>());
        var cancel=new SourcingActionInput(Command(),saved["version"]!.GetValue<string>());var cancelled=await ReadPost(customer,"/api/sourcing/requests/"+id+"/cancel",cancel,capture:"cancel");Assert.Equal(id,cancelled["id"]!.GetValue<string>());Assert.Equal("Cancelled",cancelled["state"]!.GetValue<string>());
    }
    [Fact] public async Task ConcurrentSameCommandReplaysAfterConsumptionAndDifferentPayloadConflicts()
    {
        var person=await Customer();using var customer=person.Client;var input=Input(await Select(customer,await Listing()));var responses=await Task.WhenAll(customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input),customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input));
        Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Created);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);var bodies=new List<JsonNode>();foreach(var response in responses)bodies.Add(await Body(response,response.StatusCode));Assert.Equal(bodies[0]["id"]!.GetValue<string>(),bodies[1]["id"]!.GetValue<string>());var replay=await ReadPost(customer,"/api/cart/en/sourcing/submit",input);Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(HttpStatusCode.Conflict,(await customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input with{Note="different payload"})).StatusCode);
        await using var check=fixture.Sql.Factory.Services.CreateAsyncScope();var db=check.ServiceProvider.GetRequiredService<MarketDbContext>();Assert.Equal(1,await db.SourcingRequests.CountAsync(r=>r.OwnerId==person.Owner));Assert.Equal(1,await db.SourcingCommandReceipts.CountAsync(r=>r.ActorId==person.Owner));Assert.Equal(1,await db.SourcingRequestEvents.CountAsync(e=>e.RequestId==replay["id"]!.GetValue<string>()));
    }
    [Fact] public async Task DifferentCommandsCannotConsumeTheSameCartVersionTwice()
    {
        var person=await Customer();using var customer=person.Client;var input=Input(await Select(customer,await Listing()));var responses=await Task.WhenAll(customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input),customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input with{RequestId=Command()}));try{Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Created);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);}finally{foreach(var response in responses)response.Dispose();}
        await using var check=fixture.Sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await check.ServiceProvider.GetRequiredService<MarketDbContext>().SourcingRequests.CountAsync(r=>r.OwnerId==person.Owner));
    }
    [Fact] public async Task MetadataChangesRequireFreshFingerprintAndHistoricalSnapshotSurvivesHiddenModel()
    {
        var person=await Customer();using var customer=person.Client;var listing=await Listing();var cart=await Select(customer,listing);var input=Input(cart);var modelId=cart["lines"]![0]!["candidate"]!["model"]!["id"]!.GetValue<string>();
        await using(var edit=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=edit.ServiceProvider.GetRequiredService<CatalogDbContext>();var product=await db.Products.SingleAsync(p=>p.Id==modelId);product.Featured=!product.Featured;await db.SaveChangesAsync();}
        Assert.Equal(HttpStatusCode.Conflict,(await customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input)).StatusCode);var refreshed=await Body(await customer.GetAsync("/api/cart/en/sourcing"));Assert.Equal(cart["version"]!.GetValue<string>(),refreshed["version"]!.GetValue<string>());var fresh=Input(refreshed);var saved=await Submit(customer,fresh);var id=saved["id"]!.GetValue<string>();var before=await Body(await customer.GetAsync("/api/sourcing/requests/"+id));
        await using(var edit=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=edit.ServiceProvider.GetRequiredService<CatalogDbContext>();var product=await db.Products.SingleAsync(p=>p.Id==modelId);product.Status="Hidden";await db.SaveChangesAsync();}
        Assert.Equal(before["lines"]!.ToJsonString(),(await Body(await customer.GetAsync("/api/sourcing/requests/"+id)))["lines"]!.ToJsonString());
    }
    [Fact] public async Task StateTransitionsAreVersionedReplayableAndNeverExposeStaffIdentityToCustomers()
    {
        var person=await Customer();using var customer=person.Client;var input=Input(await Select(customer,await Listing()));var saved=await Submit(customer,input);var id=saved["id"]!.GetValue<string>();using var sales=await fixture.ReuseStaff("SalesManager");var review=new SourcingActionInput(Command(),saved["version"]!.GetValue<string>());var reviewed=await ReadPost(sales,"/api/admin/sourcing/requests/"+id+"/review",review);var repeated=await ReadPost(sales,"/api/admin/sourcing/requests/"+id+"/review",review);Assert.True(repeated["replayed"]!.GetValue<bool>());Assert.Equal(reviewed["eventId"]!.GetValue<string>(),repeated["eventId"]!.GetValue<string>());
        var submissionReplay=await ReadPost(customer,"/api/cart/en/sourcing/submit",input);Assert.Equal("Submitted",submissionReplay["state"]!.GetValue<string>());Assert.Equal(saved["version"]!.GetValue<string>(),submissionReplay["version"]!.GetValue<string>());Assert.Equal("Reviewing",(await Body(await customer.GetAsync("/api/sourcing/requests/"+id)))["summary"]!["state"]!.GetValue<string>());
        var cancel=new SourcingActionInput(Command(),reviewed["version"]!.GetValue<string>());var cancelled=await ReadPost(customer,"/api/sourcing/requests/"+id+"/cancel",cancel,capture:"state-transitions-cancel");Assert.Equal("Cancelled",cancelled["state"]!.GetValue<string>());Assert.True((await ReadPost(customer,"/api/sourcing/requests/"+id+"/cancel",cancel))["replayed"]!.GetValue<bool>());
        Assert.Equal(HttpStatusCode.Conflict,(await sales.PostAsJsonAsync("/api/admin/sourcing/requests/"+id+"/unavailable",new SourcingUnavailableInput(Command(),cancelled["version"]!.GetValue<string>(),"supplier_unavailable","قابل تأمین نیست"))).StatusCode);var events=await Body(await customer.GetAsync("/api/sourcing/requests/"+id+"/events"));Assert.Equal(3,events["items"]!.AsArray().Count);Assert.Null(events["items"]![0]!["stateBefore"]);Assert.DoesNotContain("actorId",events.ToJsonString());
    }
    [Fact] public async Task ConcurrentReviewAndCustomerCancellationHaveOneWinnerAndOneEvent()
    {
        var person=await Customer();using var customer=person.Client;var saved=await Submit(customer,Input(await Select(customer,await Listing())));var id=saved["id"]!.GetValue<string>();using var sales=await fixture.ReuseStaff("SalesManager");var version=saved["version"]!.GetValue<string>();var results=await Task.WhenAll(sales.PostAsJsonAsync("/api/admin/sourcing/requests/"+id+"/review",new SourcingActionInput(Command(),version)),customer.PostAsJsonAsync("/api/sourcing/requests/"+id+"/cancel",new SourcingActionInput(Command(),version)));
