    [Fact] public async Task CustomerOwnershipAndIndependentSalesPoliciesAreEnforced()
    {
        var person=await Customer();using var customer=person.Client;var saved=await Submit(customer,Input(await Select(customer,await Listing())));var id=saved["id"]!.GetValue<string>();var other=await Customer();using var outsider=other.Client;using var anonymous=fixture.Sql.Factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync("/api/sourcing/requests/"+id)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync("/api/sourcing/requests/"+id)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync("/api/sourcing/requests/"+id+"/events")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await fixture.Content.GetAsync("/api/admin/sourcing/requests")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await fixture.Writer.GetAsync("/api/admin/sourcing/requests")).StatusCode);
