    [Fact] public async Task ReceiptFailureRollsBackRequestEventsAndCartConsumptionThenSameCommandCanRetry()
    {
        var person=await Customer();using var customer=person.Client;var cart=await Select(customer,await Listing());var input=Input(cart);await using(var setup=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=setup.ServiceProvider.GetRequiredService<MarketDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("CREATE TRIGGER [market].[RejectSourcingReceiptQa] ON [market].[SourcingCommandReceipts] INSTEAD OF INSERT AS THROW 51000,'Synthetic QA sourcing receipt failure',1;");}
        try{Assert.Equal(HttpStatusCode.InternalServerError,(await customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",input)).StatusCode);}finally{await using var cleanup=fixture.Sql.Factory.Services.CreateAsyncScope();await cleanup.ServiceProvider.GetRequiredService<MarketDbContext>().Database.ExecuteSqlRawAsync("DROP TRIGGER [market].[RejectSourcingReceiptQa];");}
        Assert.Equal(cart.ToJsonString(),(await Body(await customer.GetAsync("/api/cart/en/sourcing"))).ToJsonString());await using(var check=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=check.ServiceProvider.GetRequiredService<MarketDbContext>();Assert.False(await db.SourcingRequests.AnyAsync(r=>r.OwnerId==person.Owner));Assert.False(await db.SourcingCommandReceipts.AnyAsync(r=>r.ActorId==person.Owner));}await Submit(customer,input);
    }
    [Fact] public async Task RequestAndEventPagesAreBoundedAndCursorsBindOwnerStateAndTarget()
    {
        var person=await Customer();using var customer=person.Client;var saved=await Submit(customer,Input(await Select(customer,await Listing())));var id=saved["id"]!.GetValue<string>();var at=DateTimeOffset.UtcNow;
        await using(var setup=fixture.Sql.Factory.Services.CreateAsyncScope()){var services=setup.ServiceProvider;var db=services.GetRequiredService<MarketDbContext>();var protection=services.GetRequiredService<ISourcingNoteProtection>();for(var i=0;i<52;i++){var request=Id();db.SourcingRequests.Add(new(){Id=request,OwnerId=person.Owner,SubmitRequestId=Id(),PayloadHash=new string('A',64),CartId=Id(),SubmittedCartVersion="AAAAAAAAAAE=",Locale="en",State="Submitted",ProtectedNote=protection.Protect(person.Owner,request,""),CreatedAt=at.AddMinutes(-i-1),ChangedAt=at.AddMinutes(-i-1),Lines=[new(){RequestId=request,ListingId=Id(),ModelId="synthetic-page-model",Quantity=1,NameFa="درخواست صفحهٔ نمونه",NameEn="Synthetic page request",SourceKey="qa",SourceItemKey=Id()}]});}for(var i=0;i<45;i++)db.SourcingRequestEvents.Add(new(){RequestId=id,ActorId=person.Owner,ActorKind="customer",StateBefore="Submitted",StateAfter="Submitted",ReasonCode="synthetic_page_history",At=at.AddSeconds(i)});await db.SaveChangesAsync();}
        var page=await Body(await customer.GetAsync("/api/sourcing/requests"));Assert.Equal(20,page["items"]!.AsArray().Count);var cursor=page["nextCursor"]!.GetValue<string>();Assert.InRange(cursor.Length,1,200);Assert.Equal(20,(await Body(await customer.GetAsync("/api/sourcing/requests?cursor="+Uri.EscapeDataString(cursor))))["items"]!.AsArray().Count);Assert.Equal(HttpStatusCode.BadRequest,(await customer.GetAsync("/api/sourcing/requests?state=Reviewing&cursor="+Uri.EscapeDataString(cursor))).StatusCode);using var sales=await fixture.ReuseStaff("SalesManager");Assert.Equal(HttpStatusCode.BadRequest,(await sales.GetAsync("/api/admin/sourcing/requests?cursor="+Uri.EscapeDataString(cursor))).StatusCode);Assert.Equal(50,(await Body(await sales.GetAsync("/api/admin/sourcing/requests")))["items"]!.AsArray().Count);
        var history=await Body(await customer.GetAsync("/api/sourcing/requests/"+id+"/events"));Assert.Equal(20,history["items"]!.AsArray().Count);var after=history["nextCursor"]!.GetValue<string>();Assert.InRange(after.Length,1,200);Assert.Equal(20,(await Body(await customer.GetAsync("/api/sourcing/requests/"+id+"/events?cursor="+Uri.EscapeDataString(after))))["items"]!.AsArray().Count);var other=page["items"]![1]!["id"]!.GetValue<string>();Assert.Equal(HttpStatusCode.BadRequest,(await customer.GetAsync("/api/sourcing/requests/"+other+"/events?cursor="+Uri.EscapeDataString(after))).StatusCode);
    }
    [Fact] public async Task ReceiptLookupIsReadOnlyActorOperationAndTargetBoundAndKeepsTheOriginalSnapshot()
    {
        var person=await Customer();using var customer=person.Client;var input=Input(await Select(customer,await Listing()));var submitted=await Submit(customer,input);var id=submitted["id"]!.GetValue<string>();var route="/api/sourcing/requests/commands/submit/"+input.RequestId;var original=await Body(await customer.GetAsync(route),capture:"receipt-lookup-submit-receipt");Assert.True(original["replayed"]!.GetValue<bool>());Assert.Equal(submitted["version"]!.GetValue<string>(),original["version"]!.GetValue<string>());
        var outsider=await Customer();using var other=outsider.Client;Assert.Equal(HttpStatusCode.NotFound,(await other.GetAsync(route)).StatusCode);using var anonymous=fixture.Sql.Factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync(route)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await customer.GetAsync("/api/sourcing/requests/commands/review/"+input.RequestId)).StatusCode);
        using var sales=await fixture.ReuseStaff("SalesManager");var action=new SourcingActionInput(Command(),submitted["version"]!.GetValue<string>());var reviewed=await ReadPost(sales,"/api/admin/sourcing/requests/"+id+"/review",action);var adminRoute="/api/admin/sourcing/requests/"+id+"/commands/review/"+action.RequestId;var receipt=await Body(await sales.GetAsync(adminRoute),capture:"admin-receipt");Assert.Equal(reviewed["eventId"]!.GetValue<string>(),receipt["eventId"]!.GetValue<string>());Assert.Equal("Submitted",(await Body(await customer.GetAsync(route)))["state"]!.GetValue<string>());Assert.Equal("Reviewing",(await Body(await customer.GetAsync("/api/sourcing/requests/"+id)))["summary"]!["state"]!.GetValue<string>());
        Assert.Equal(HttpStatusCode.NotFound,(await sales.GetAsync("/api/admin/sourcing/requests/"+Id()+"/commands/review/"+action.RequestId)).StatusCode);using var anotherWriter=await fixture.Staff("SalesManager");Assert.Equal(HttpStatusCode.NotFound,(await anotherWriter.GetAsync(adminRoute)).StatusCode);
        await using var check=fixture.Sql.Factory.Services.CreateAsyncScope();var db=check.ServiceProvider.GetRequiredService<MarketDbContext>();Assert.Equal(2,await db.SourcingRequestEvents.CountAsync(e=>e.RequestId==id));Assert.Equal(2,await db.SourcingCommandReceipts.CountAsync(r=>r.TargetId==id));Assert.False((await db.SourcingRequests.SingleAsync(r=>r.Id==id)).State=="Submitted");
    }
    [Fact] public async Task StaffCanMarkUnavailableWithPublicReasonAndTheTerminalResultIsReplayable()
    {
        var person=await Customer();using var customer=person.Client;var saved=await Submit(customer,Input(await Select(customer,await Listing(availability:"unavailable"))));var id=saved["id"]!.GetValue<string>();using var sales=await fixture.ReuseStaff("SalesManager");var input=new SourcingUnavailableInput(Command(),saved["version"]!.GetValue<string>(),"supplier_unavailable","این مدل اکنون قابل تأمین نیست؛ نمونهٔ آزمون SQL.");var route="/api/admin/sourcing/requests/"+id+"/unavailable";
        Assert.Equal(HttpStatusCode.BadRequest,(await sales.PostAsJsonAsync(route,input with{PublicMessage=" "})).StatusCode);var unavailable=await ReadPost(sales,route,input);Assert.Equal("Unavailable",unavailable["state"]!.GetValue<string>());Assert.True((await ReadPost(sales,route,input))["replayed"]!.GetValue<bool>());Assert.Equal(HttpStatusCode.Conflict,(await sales.PostAsJsonAsync(route,input with{PublicMessage="different"})).StatusCode);
        var detail=await Body(await customer.GetAsync("/api/sourcing/requests/"+id));Assert.False(detail["canCancel"]!.GetValue<bool>());Assert.False(detail["canPay"]!.GetValue<bool>());var history=await Body(await customer.GetAsync("/api/sourcing/requests/"+id+"/events"));Assert.Equal(2,history["items"]!.AsArray().Count);Assert.Equal(input.PublicMessage,history["items"]![1]!["publicMessage"]!.GetValue<string>());
    }
    [Fact] public async Task RootAdminAuditFailureRollsBackTransitionEventReceiptAndRequestVersion()
    {
        var person=await Customer();using var customer=person.Client;var saved=await Submit(customer,Input(await Select(customer,await Listing())));var id=SourcingRules.Id(saved["id"]!.GetValue<string>());using var sales=await fixture.ReuseStaff("SalesManager");var input=new SourcingActionInput(Command(),saved["version"]!.GetValue<string>());var route="/api/admin/sourcing/requests/"+id+"/review";
        // CHECK DDL requires a literal: identifiers are static and bracket-quoted,
        // and the only variable value is a validated UUID in a quoted SQL string.
        var rejectAuditSql="ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT [CK_SourcingAuditFailure] CHECK ([Resource]<>N'"+route.Replace("'","''",StringComparison.Ordinal)+"')";
        await using(var setup=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=setup.ServiceProvider.GetRequiredService<IdentityDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync(rejectAuditSql);}
        try{Assert.Equal(HttpStatusCode.Conflict,(await sales.PostAsJsonAsync(route,input)).StatusCode);}finally{await using var cleanup=fixture.Sql.Factory.Services.CreateAsyncScope();await cleanup.ServiceProvider.GetRequiredService<IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT [CK_SourcingAuditFailure]");}
        var unchanged=await Body(await customer.GetAsync("/api/sourcing/requests/"+id));Assert.Equal("Submitted",unchanged["summary"]!["state"]!.GetValue<string>());Assert.Equal(saved["version"]!.GetValue<string>(),unchanged["summary"]!["version"]!.GetValue<string>());
        await using(var check=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=check.ServiceProvider.GetRequiredService<MarketDbContext>();Assert.Equal(1,await db.SourcingRequestEvents.CountAsync(e=>e.RequestId==id));Assert.Equal(1,await db.SourcingCommandReceipts.CountAsync(r=>r.TargetId==id));Assert.False(await check.ServiceProvider.GetRequiredService<IdentityDbContext>().Audit.AnyAsync(a=>a.Resource==route));}await ReadPost(sales,route,input);
    }
